// ==========================================
// GAME LOGIC (THE BRAIN)
// ==========================================
void farmEscape::on_Tick(uint32_t currentTime, uint32_t deltaTime)
{
    gameTime = currentTime;

    // Decrease the cooldown timer by deltaTime
    if (twistCooldown > 0)
    {
        twistCooldown -= (int)deltaTime;
    }

    if (lives <= 0)
    {
        return;
    }

    // --- REBALANCED ROUND PROGRESSION ---
    scoreTimer += deltaTime;
    if (scoreTimer >= 1000)
    {
        score += 1;
        scoreTimer = 0;

        // Rounds increase every 25 seconds
        currentRound = (score / 25) + 1;

        // Fences break gradually faster. 
        // Round 1: 7000ms | Round 6: 5000ms | Round 12: 2600ms
        breakInterval = 7000 - ((currentRound - 1) * 400);

        // Cap to ensure it never becomes faster than the player's 2-second cooldown
        if (breakInterval < 2500)
        {
            breakInterval = 2500;
        }
    }
    
    // 1. THE BREAK TIMER
    breakTimer += deltaTime;
    if (breakTimer >= breakInterval)
    {
        breakTimer = 0;

        for (int i = 0; i < 3; i++)
        {
            if (fenceState[i] == 2)
            {
                fenceState[i] = 0;
            }
        }

        // Find all currently safe fences (0)
        int candidates[3];
        int count = 0;
        for (int i = 0; i < 3; i++)
        {
            if (fenceState[i] == 0)
            {
                candidates[count++] = i;
            }
        }

        // --- REBALANCED BREAK CHAOS ---
        if (count > 0)
        {
            int maxToBreak = 1;
            if (currentRound >= 5) maxToBreak = 2; // Double breaks unlock at Round 5
            if (currentRound >= 8) maxToBreak = 3; // Triple breaks unlock at Round 8

            int numToBreak = (rand() % maxToBreak) + 1; 
            
            if (numToBreak > count) 
            {
                numToBreak = count;
            }

            for (int b = 0; b < numToBreak; b++)
            {
                int pickIndex = rand() % count;
                int screenToBreak = candidates[pickIndex];
                
                fenceState[screenToBreak] = 1; // Break it!

                candidates[pickIndex] = candidates[count - 1];
                count--;
            }
        }
    }

    // 2. MOVE THE CHICKEN
    for (int c = 0; c < 3; c++)
    {
        Chicken &ch = chickens[c]; 

        // --- 1. WANDER: Realistic & Scaling Chicken Behavior ---
        ch.wanderTimer -= (int)deltaTime;
        if (ch.wanderTimer <= 0)
        {
            // 30% chance to stop and "peck", 70% chance to walk
            if (rand() % 10 < 3) 
            {
                ch.speedX = 0;
                ch.speedY = 0;
                ch.wanderTimer = 500 + (rand() % 1000); 
            } 
            else 
            {
                // Dynamic speed limit based on round
                // R1-R2: Limit 2 | R3-R5: Limit 3 | R6-R8: Limit 4 | R9+: Limit 5
                int speedLimit = 2 + (currentRound / 3); 
                if (speedLimit > 5) speedLimit = 5;

                // Smoothly choose a new direction, bounded by the current round's limit
                ch.speedX = (rand() % ((speedLimit * 2) + 1)) - speedLimit; 
                ch.speedY = (rand() % (speedLimit + 2)) - 1; // Bias slightly downwards

                ch.wanderTimer = 1000 + (rand() % 2000); // Walk for 1 to 3s
            }
        }

        // --- 2. MOVE ---
        ch.x += ch.speedX;
        ch.y += ch.speedY;

        // --- 3. SCREEN HOPPING (Contiguous Farm) ---
        if (ch.x > 240)
        {
            ch.x = 0;
            ch.currentScreen = (ch.currentScreen + 1) % 3; 
        }
        else if (ch.x < 0)
        {
            ch.x = 240;
            ch.currentScreen = (ch.currentScreen + 2) % 3; // +2 is the same as -1 with modulo 3
        }

        // --- 4. TOP WALL BOUNCE ---
        if (ch.y < 30)
        {
            ch.y = 30;
            ch.speedY = abs(ch.speedY); // Force a gentle downward bounce
            if (ch.speedY == 0) ch.speedY = 2; // Prevent getting stuck on the wall
        }

        // --- 5. BOTTOM ESCAPE ZONE ---
        if (ch.y > 220)
        {
            if (fenceState[ch.currentScreen] == 1) // Broken gap!
            {
                lives -= 1;
                if (lives < 0) lives = 0;

                // Respawn this specific chicken back at the top of its current screen
                ch.y = 50; 
                ch.speedX = (rand() % 5) - 2;
                ch.speedY = 2; // Walk down
                ch.wanderTimer = 1500;
            }
            else // Fence is patched/safe
            {
                ch.y = 220;
                ch.speedY = -abs(ch.speedY); // Bounce back up safely
                if (ch.speedY == 0) ch.speedY = -2;
            }
        }
    }
}

