void farmEscape::on_Render(std::array<Cubios::Screen, 3> &screens)
{
    for (auto it = screens.begin(); it != screens.end(); ++it)
    {
        int screenID = it->ID();
        Cubios::GFX_setRenderTarget(screenID);
        Cubios::GFX_clear(Cubios::Gfx::Colors::darkGreen);

        // --- NEW: GLOBAL GAME OVER OVERRIDE ---
        // This overrides everything and forces every screen to show the Game Over state
        if (lives <= 0)
        {
            Cubios::GFX_drawText(120, 100, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::red, "GAME OVER");
            std::string finalScore = "FINAL SCORE: " + std::to_string(score);
            Cubios::GFX_drawText(120, 140, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::cyan, finalScore.c_str());
            Cubios::GFX_drawText(120, 120, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::white, "TAP TO RESTART");
            
            Cubios::GFX_render();
            continue; // CRITICAL: This skips drawing the fences, HUD, and chickens for this screen
        }

        // 1. LIVES HUD
        if (screenID == 0)
        {
            std::string livesStr = "            LIVES: " + std::to_string(lives);
            std::string roundStr = "ROUND: " + std::to_string(currentRound);
            std::string scoreStr = "            SCORE: " + std::to_string(score);

            Cubios::GFX_drawText(10, 15, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::yellow, livesStr.c_str());
            Cubios::GFX_drawText(120, 120, 5, 3, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::black, roundStr.c_str());
            Cubios::GFX_drawText(10, 35, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::cyan, scoreStr.c_str());
        }

        // 2. FARM
        if (screenID == 1)
        {
            Cubios::GFX_drawText(120, 80, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::white, "  /\\  ");
            Cubios::GFX_drawText(120, 90, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::white, " /__\\ ");
            Cubios::GFX_drawText(120, 100, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::white, "|FARM|");
        }

        // 3. Top Fence
        Cubios::GFX_drawText(120, 25, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::white, "===================================");

        // COOLDOWN INDICATOR
        if (twistCooldown > 0)
        {
            int secondsLeft = (twistCooldown + 999) / 1000; 
            std::string waitStr = "WAIT: " + std::to_string(secondsLeft) + "s";
            
            Cubios::GFX_drawText(120, 45, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::magenta, waitStr.c_str());
        }

        // 4. THE 3-STATE BOTTOM FENCE
        if (fenceState[screenID] == 1)
        {
            // State 1: Broken Gap
            Cubios::GFX_drawText(120, 230, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::red, "[==    GAP    ==]");
        }
        else if (fenceState[screenID] == 2)
        {
            // State 2: Patched
            Cubios::GFX_drawText(120, 230, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::blue, "[++++ PATCHED ++++]");
        }
        else
        {
            // State 0: Normal Safe Wall
            Cubios::GFX_drawText(120, 230, 8, 0, Cubios::text_align_t::TEXT_ALIGN_CENTER, Cubios::Gfx::Colors::white, "[====================]");
        }

        // 5. Draw the Animated Chicken
        for (int c = 0; c < 3; c++)
        {
            if (chickens[c].currentScreen == screenID)
            {
                const char *frame = ((gameTime / 250) % 2 == 0) ? "\\(o)/" : "/(o)\\";
                
                // Show a pecking/standing sprite if stationary
                if (chickens[c].speedX == 0 && chickens[c].speedY == 0) 
                {
                    frame = "-(o)-";
                }

                Cubios::GFX_drawText(chickens[c].x, chickens[c].y, 8, 0,
                                     Cubios::text_align_t::TEXT_ALIGN_CENTER,
                                     Cubios::Gfx::Colors::yellow, frame);
            }
        }

        Cubios::GFX_render();
    }
}

