void farmEscape::on_Twist(const Cubios::TOPOLOGY_twistInfo_t &twist)
{
    // 1. GAME OVER RESET
    if (lives <= 0)
    {
        lives = 5;
        currentRound = 1;
        score = 0;
        breakInterval = 7000;
        breakTimer = 0;
        scoreTimer = 0;
        twistCooldown = 0; // Reset cooldown
        
        // Reset all three chickens to their starting states
        chickens[0] = {60, 100, 4, 3, 0, 2000};
        chickens[1] = {120, 120, -5, 4, 1, 1500};
        chickens[2] = {180, 80, 3, -2, 2, 2800};
        
        fenceState[0] = 0;
        fenceState[1] = 0;
        fenceState[2] = 0;
        return;
    }

    // Check if the cooldown is active
    if (twistCooldown > 0)
    {
        // Still on cooldown! Ignore the twist.
        return; 
    }

    // 2. MASS REPAIR (OS Update Fix)
    // Fixes ALL broken fences on the cube at once.
    bool repairedSomething = false;
    for (int screenID = 0; screenID < 3; screenID++)
    {
        if (fenceState[screenID] == 1)
        {
            fenceState[screenID] = 2; // Patch it!
            repairedSomething = true; // We successfully fixed at least one fence
        }
    }

    // Only apply the cooldown if we actually fixed something
    if (repairedSomething)
    {
        twistCooldown = 3000;
    }
}

void farmEscape::on_Pat(uint32_t count)
{
    if (lives <= 0)
    {
        lives = 5;
        currentRound = 1;
        score = 0;
        breakInterval = 7000;
        breakTimer = 0;
        scoreTimer = 0;
        twistCooldown = 0;
        
        chickens[0] = {60, 100, 4, 3, 0, 2000};
        chickens[1] = {120, 120, -5, 4, 1, 1500};
        chickens[2] = {180, 80, 3, -2, 2, 2800};
        
        fenceState[0] = 0;
        fenceState[1] = 0;
        fenceState[2] = 0;
        return;
    }

    // Change any Broken fence (1) into a Patched fence (2) by PROXIMITY CHECK
    for (int c = 0; c < 3; c++)
    {
        int activeScreen = chickens[c].currentScreen;
        if (fenceState[activeScreen] == 1)
        {
            fenceState[activeScreen] = 2;
        }
    }
}

